package com.familyguard.child;
import android.app.Activity;import android.app.AlertDialog;import android.media.MediaRecorder;import java.io.File;import android.media.projection.MediaProjectionManager;import android.content.Intent;import android.provider.MediaStore;import android.graphics.Bitmap;import java.io.ByteArrayOutputStream;import com.google.firebase.storage.FirebaseStorage;import android.os.Bundle;import android.os.Build;import android.app.AppOpsManager;import android.app.usage.UsageStats;import android.app.usage.UsageStatsManager;import android.provider.Settings;import android.content.Context;import android.widget.*;
import com.google.firebase.FirebaseApp;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.firestore.*;import java.util.*;
public class MainActivity extends Activity{
 LinearLayout root;EditText code;TextView status;FirebaseAuth auth;FirebaseFirestore db;String parentUid;ListenerRegistration listener,screenRequestListener;String activeScreenSession;Button startLocation,usageReport,enableAppBlocking,enableWebsiteFiltering,cameraSnapshot,screenSnapshot,audioShare;MediaRecorder audioRecorder;File audioFile;boolean recordingAudio=false;
 public void onCreate(Bundle b){super.onCreate(b);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,40,32,24);root.setBackgroundColor(0xFFF5F7FB);TextView title=new TextView(this);title.setText("FamilyGuard Child");title.setTextSize(27);TextView info=new TextView(this);info.setText("Pairing and location sharing are visible on this device.");code=new EditText(this);code.setSingleLine(true);code.setHint("8-character Parent code");Button pair=new Button(this);pair.setText("Pair with Parent");pair.setOnClickListener(v->pair());status=new TextView(this);status.setText("Connecting to Firebase...");root.addView(title);root.addView(info);root.addView(code);root.addView(pair);root.addView(status);setContentView(root);try{FirebaseApp.initializeApp(this);auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();auth.signInAnonymously().addOnSuccessListener(x->{parentUid=getSharedPreferences("familyguard_child",MODE_PRIVATE).getString("parent_uid",null);if(parentUid!=null){status.setText("Connected and paired. Parent UID: "+parentUid);showRequests();}else status.setText("Connected. Enter the code from Parent app.");}).addOnFailureListener(e->status.setText("Sign-in failed: "+e.getMessage()));}catch(Exception e){status.setText("Firebase setup error: "+e.getMessage());}}
 void pair(){String c=code.getText().toString().trim().toUpperCase(Locale.US);if(c.length()!=8){status.setText("Enter the full 8-character code.");return;}db.collection("pairCodes").document(c).get().addOnSuccessListener(doc->{if(!doc.exists()){status.setText("Invalid code.");return;}Date exp=doc.getDate("expiresAt");String p=doc.getString("parentUid");String used=doc.getString("consumedBy");if(exp==null||exp.before(new Date())||p==null||(used!=null&&!used.isEmpty())){status.setText("Code expired or already used.");return;}parentUid=p;String uid=auth.getUid();db.collection("pairCodes").document(c).update("consumedBy",uid).addOnSuccessListener(v->{Map<String,Object>link=new HashMap<>();link.put("parentUid",p);link.put("childUid",uid);link.put("childLabel",Build.MODEL);link.put("pairCode",c);link.put("pairedAt",FieldValue.serverTimestamp());db.collection("familyLinks").document(uid).set(link).addOnSuccessListener(x->{getSharedPreferences("familyguard_child",MODE_PRIVATE).edit().putString("parent_uid",p).apply();status.setText("Paired. Request Location permission from Parent.");showRequests();}).addOnFailureListener(e->status.setText("Link failed: "+e.getMessage()));}).addOnFailureListener(e->status.setText("Code was already used or could not be confirmed."));}).addOnFailureListener(e->status.setText("Pairing lookup failed: "+e.getMessage()));}
 void showRequests(){String[] names={"Location","Camera","Microphone","Usage Access","Notifications"};for(String n:names){Button b=new Button(this);b.setText("Request "+n);b.setOnClickListener(v->request(n));root.addView(b);}startLocation=new Button(this);startLocation.setText("Start visible location sharing");startLocation.setEnabled(false);startLocation.setOnClickListener(v->startLocationSharing());root.addView(startLocation);usageReport=new Button(this);usageReport.setText("Share usage report now");usageReport.setOnClickListener(v->shareUsageReport());root.addView(usageReport);enableAppBlocking=new Button(this);enableAppBlocking.setText("Enable app restrictions (Android Accessibility Settings)");enableAppBlocking.setOnClickListener(v->{status.setText("On the next screen, manually enable FamilyGuard app restrictions. This service only checks app changes to enforce Parent-selected blocks.");try{startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}catch(Exception e){status.setText("Cannot open Accessibility Settings: "+e.getMessage());}});root.addView(enableAppBlocking);enableWebsiteFiltering=new Button(this);enableWebsiteFiltering.setText("Enable website filtering (VPN permission)");enableWebsiteFiltering.setOnClickListener(v->requestWebsiteVpn());root.addView(enableWebsiteFiltering);cameraSnapshot=new Button(this);cameraSnapshot.setText("Take and share a camera snapshot");cameraSnapshot.setOnClickListener(v->takeChildApprovedSnapshot());root.addView(cameraSnapshot);screenSnapshot=new Button(this);screenSnapshot.setText("Take and share a one-time screen snapshot");screenSnapshot.setOnClickListener(v->requestScreenSnapshot());root.addView(screenSnapshot);audioShare=new Button(this);audioShare.setText("Start Child-approved audio recording");audioShare.setOnClickListener(v->toggleAudioRecording());root.addView(audioShare);Button stopMirror=new Button(this);stopMirror.setText("Stop live screen sharing");stopMirror.setOnClickListener(v->{stopService(new Intent(this,ScreenMirrorService.class));status.setText("Live screen sharing stopped.");});root.addView(stopMirror);watch();watchScreenMirrorRequests();}
 void watchScreenMirrorRequests(){
  if(screenRequestListener!=null)screenRequestListener.remove();
  screenRequestListener=db.collection("screenSessions").whereEqualTo("childUid",auth.getUid()).whereEqualTo("status","requested").addSnapshotListener((snap,error)->{
   if(error!=null||snap==null)return;
   for(DocumentSnapshot session:snap.getDocuments()){
    String id=session.getId();if(id.equals(activeScreenSession))continue;activeScreenSession=id;
    new AlertDialog.Builder(this).setTitle("Parent requests live screen sharing")
     .setMessage("The paired Parent wants to view this phone's screen live. Android will show its screen-sharing consent dialog and a persistent notification. Allow only if you agree.")
     .setNegativeButton("Deny",(dialog,which)->session.getReference().update("status","denied","updatedAt",FieldValue.serverTimestamp()).addOnFailureListener(e->status.setText("Could not deny request: "+e.getMessage())))
     .setPositiveButton("Allow & continue",(dialog,which)->{
       MediaProjectionManager manager=(MediaProjectionManager)getSystemService(Context.MEDIA_PROJECTION_SERVICE);
       if(manager==null){session.getReference().update("status","denied");status.setText("Screen sharing is unavailable on this device.");return;}
       status.setText("Android will ask for screen-sharing consent. Nothing streams unless you approve.");
       startActivityForResult(manager.createScreenCaptureIntent(),108);
     }).setOnCancelListener(dialog->session.getReference().update("status","denied")).show();
   }
  });
 }
 void requestWebsiteVpn(){if(parentUid==null){status.setText("Pair this Child device first.");return;}Intent prepare=android.net.VpnService.prepare(this);if(prepare!=null){startActivityForResult(prepare,104);}else startWebsiteVpn();}
 void startWebsiteVpn(){Intent i=new Intent(this,WebsiteFilterVpnService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);status.setText("Website filtering VPN started. Android shows its VPN indicator and ongoing notification.");}
 @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==104){if(resultCode==RESULT_OK)startWebsiteVpn();else status.setText("VPN permission declined. Website filtering remains off.");}else if(requestCode==105){if(resultCode==RESULT_OK&&data!=null&&data.getExtras()!=null){Object image=data.getExtras().get("data");if(image instanceof Bitmap)uploadChildApprovedSnapshot((Bitmap)image);else status.setText("Camera returned no image.");}else status.setText("Camera snapshot cancelled. Nothing was uploaded.");}else if(requestCode==106){if(resultCode==RESULT_OK&&data!=null){Intent service=new Intent(this,ScreenSnapshotService.class);service.putExtra("resultCode",resultCode);service.putExtra("projectionData",data);if(Build.VERSION.SDK_INT>=26)startForegroundService(service);else startService(service);status.setText("Screen capture started. Android displays its screen-sharing indicator/notification; one frame will be shared.");}else status.setText("Screen snapshot cancelled. Nothing was uploaded.");}else if(requestCode==108){if(resultCode==RESULT_OK&&data!=null&&activeScreenSession!=null){Intent service=new Intent(this,ScreenMirrorService.class);service.putExtra("sessionId",activeScreenSession);service.putExtra("resultCode",resultCode);service.putExtra("projectionData",data);if(Build.VERSION.SDK_INT>=26)startForegroundService(service);else startService(service);status.setText("Live screen sharing started after your approval. Tap Stop live screen sharing to end.");}else{if(activeScreenSession!=null)db.collection("screenSessions").document(activeScreenSession).update("status","denied","updatedAt",FieldValue.serverTimestamp());status.setText("Screen sharing consent declined. No screen data was sent.");}}} 
 void toggleAudioRecording(){if(recordingAudio){stopAndShareAudio();return;}if(parentUid==null){status.setText("Pair this Child device first.");return;}if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},107);return;}startAudioRecording();}
 void startAudioRecording(){try{audioFile=new File(getCacheDir(),"familyguard-audio-"+System.currentTimeMillis()+".m4a");audioRecorder=Build.VERSION.SDK_INT>=31?new MediaRecorder(this):new MediaRecorder();audioRecorder.setAudioSource(MediaRecorder.AudioSource.MIC);audioRecorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);audioRecorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);audioRecorder.setAudioEncodingBitRate(64000);audioRecorder.setAudioSamplingRate(22050);audioRecorder.setOutputFile(audioFile.getAbsolutePath());audioRecorder.prepare();audioRecorder.start();recordingAudio=true;audioShare.setText("Stop and share audio recording");status.setText("Microphone recording is active in this Child app for up to 60 seconds. Tap Stop and share; leaving the app cancels the recording.");new android.os.Handler(getMainLooper()).postDelayed(()->{if(recordingAudio)stopAndShareAudio();},60000);}catch(Exception e){cancelAudioRecording();status.setText("Could not start audio recording: "+e.getMessage());}}
 void stopAndShareAudio(){if(!recordingAudio)return;try{audioRecorder.stop();}catch(Exception e){cancelAudioRecording();status.setText("Recording was too short or failed; no audio shared.");return;}try{audioRecorder.release();}catch(Exception ignored){}audioRecorder=null;recordingAudio=false;if(audioShare!=null)audioShare.setText("Start Child-approved audio recording");if(audioFile==null||!audioFile.exists()||audioFile.length()==0){status.setText("No audio data was recorded.");return;}File completedFile=audioFile;audioFile=null;uploadChildApprovedAudio(completedFile);}
 void cancelAudioRecording(){recordingAudio=false;if(audioRecorder!=null){try{audioRecorder.reset();}catch(Exception ignored){}try{audioRecorder.release();}catch(Exception ignored){}audioRecorder=null;}if(audioShare!=null)audioShare.setText("Start Child-approved audio recording");if(audioFile!=null){audioFile.delete();audioFile=null;}}
 void uploadChildApprovedAudio(File file){if(auth==null||auth.getUid()==null||parentUid==null)return;status.setText("Uploading Child-approved audio…");String uid=auth.getUid();long stamp=System.currentTimeMillis();String path="audioMessages/"+uid+"/"+stamp+".m4a";FirebaseStorage.getInstance().getReference().child(path).putFile(android.net.Uri.fromFile(file),new com.google.firebase.storage.StorageMetadata.Builder().setContentType("audio/mp4").build()).addOnSuccessListener(task->FirebaseStorage.getInstance().getReference().child(path).getDownloadUrl().addOnSuccessListener(uri->{Map<String,Object> meta=new HashMap<>();meta.put("childUid",uid);meta.put("parentUid",parentUid);meta.put("storagePath",path);meta.put("downloadUrl",uri.toString());meta.put("createdAt",FieldValue.serverTimestamp());meta.put("captureType","child_initiated_audio_recording");db.collection("audioMessages").add(meta).addOnSuccessListener(v->{status.setText("Child-approved audio shared with Parent.");file.delete();}).addOnFailureListener(e->status.setText("Audio uploaded but record save failed: "+e.getMessage()));}).addOnFailureListener(e->status.setText("Could not create audio link: "+e.getMessage()))).addOnFailureListener(e->status.setText("Audio upload failed. Check Firebase Storage rules: "+e.getMessage()));}
 void requestScreenSnapshot(){if(parentUid==null){status.setText("Pair this Child device first.");return;}MediaProjectionManager manager=(MediaProjectionManager)getSystemService(Context.MEDIA_PROJECTION_SERVICE);if(manager==null){status.setText("Screen capture is not available on this device.");return;}status.setText("Android will ask you to approve screen sharing. Approve only if you want to share one screen image with Parent.");startActivityForResult(manager.createScreenCaptureIntent(),106);}
 void takeChildApprovedSnapshot(){if(parentUid==null){status.setText("Pair this Child device first.");return;}Intent camera=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);if(camera.resolveActivity(getPackageManager())==null){status.setText("No camera app is available.");return;}status.setText("Camera will open visibly. Take a photo to share it with the paired Parent, or cancel.");startActivityForResult(camera,105);}
 void uploadChildApprovedSnapshot(Bitmap bitmap){if(auth==null||auth.getUid()==null||parentUid==null)return;status.setText("Uploading the Child-approved snapshot…");ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,80,out);byte[] bytes=out.toByteArray();long stamp=System.currentTimeMillis();String uid=auth.getUid();String path="cameraSnapshots/"+uid+"/"+stamp+".jpg";FirebaseStorage.getInstance().getReference().child(path).putBytes(bytes).addOnSuccessListener(task->FirebaseStorage.getInstance().getReference().child(path).getDownloadUrl().addOnSuccessListener(uri->{Map<String,Object> meta=new HashMap<>();meta.put("childUid",uid);meta.put("parentUid",parentUid);meta.put("storagePath",path);meta.put("downloadUrl",uri.toString());meta.put("createdAt",FieldValue.serverTimestamp());meta.put("captureType","child_initiated_camera_thumbnail");db.collection("cameraSnapshots").add(meta).addOnSuccessListener(v->status.setText("Snapshot shared with Parent. This was a one-time Child-initiated photo, not live remote camera.")).addOnFailureListener(e->status.setText("Photo uploaded but metadata save failed: "+e.getMessage()));}).addOnFailureListener(e->status.setText("Could not get photo link: "+e.getMessage()))).addOnFailureListener(e->status.setText("Snapshot upload failed. Check Firebase Storage setup/rules: "+e.getMessage()));}
 void request(String permission){Map<String,Object>d=new HashMap<>();d.put("parentUid",parentUid);d.put("childUid",auth.getUid());d.put("childLabel",Build.MODEL);d.put("permission",permission);d.put("status","pending");d.put("createdAt",FieldValue.serverTimestamp());db.collection("approvalRequests").add(d).addOnSuccessListener(x->status.setText(permission+" request sent. Wait for Parent approval.")).addOnFailureListener(e->status.setText("Request failed: "+e.getMessage()));}
 void watch(){if(listener!=null)listener.remove();listener=db.collection("approvalRequests").whereEqualTo("childUid",auth.getUid()).addSnapshotListener((s,e)->{if(e!=null||s==null)return;for(DocumentSnapshot d:s){String state=d.getString("status");String permission=d.getString("permission");if("approved".equals(state)){status.setText("Parent approved "+permission+". Confirm Android permission on this phone.");if("Location".equals(permission))requestLocationPermission();else if("Camera".equals(permission))requestSystemPermission(android.Manifest.permission.CAMERA,101);else if("Microphone".equals(permission))requestSystemPermission(android.Manifest.permission.RECORD_AUDIO,102);else if("Usage Access".equals(permission))openUsageAccessSettings();}else if("denied".equals(state))status.setText("Parent denied "+permission+".");}});}
 void requestLocationPermission(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},103);}else enableLocationStart();}
 void requestSystemPermission(String p,int c){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(p)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{p},c);else status.setText(p+" permission already granted. Capture still requires a separate visible session.");}

 void openUsageAccessSettings(){status.setText("Enable Usage Access for FamilyGuard on this phone, then return here.");try{startActivity(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS));}catch(Exception e){status.setText("Cannot open Usage Access settings: "+e.getMessage());}}
 boolean hasUsageAccess(){try{AppOpsManager a=(AppOpsManager)getSystemService(Context.APP_OPS_SERVICE);int mode=a.checkOpNoThrow(AppOpsManager.OPSTR_GET_USAGE_STATS,android.os.Process.myUid(),getPackageName());return mode==AppOpsManager.MODE_ALLOWED;}catch(Exception e){return false;}}
 void shareUsageReport(){if(parentUid==null||auth==null||auth.getUid()==null){status.setText("Pair this Child device first.");return;}if(!hasUsageAccess()){status.setText("Usage Access is not enabled. Ask Parent for approval, then enable it in Android Settings.");return;}try{long end=System.currentTimeMillis(),start=end-24L*60L*60L*1000L;UsageStatsManager mgr=(UsageStatsManager)getSystemService(Context.USAGE_STATS_SERVICE);List<UsageStats> stats=mgr.queryUsageStats(UsageStatsManager.INTERVAL_DAILY,start,end);Map<String,Long> totals=new HashMap<>();if(stats!=null)for(UsageStats u:stats){long t=u.getTotalTimeInForeground();if(t>0&&!getPackageName().equals(u.getPackageName()))totals.put(u.getPackageName(),totals.getOrDefault(u.getPackageName(),0L)+t);}List<Map.Entry<String,Long>> ranked=new ArrayList<>(totals.entrySet());ranked.sort((a,b)->Long.compare(b.getValue(),a.getValue()));List<Map<String,Object>> apps=new ArrayList<>();for(int i=0;i<Math.min(20,ranked.size());i++){Map<String,Object> app=new HashMap<>();app.put("packageName",ranked.get(i).getKey());app.put("foregroundMillis",ranked.get(i).getValue());apps.add(app);}Map<String,Object> report=new HashMap<>();report.put("childUid",auth.getUid());report.put("parentUid",parentUid);report.put("periodStart",start);report.put("periodEnd",end);report.put("apps",apps);report.put("appCount",apps.size());report.put("generatedAt",FieldValue.serverTimestamp());db.collection("usageReports").document(auth.getUid()).set(report).addOnSuccessListener(v->status.setText("Usage report shared with Parent: last 24 hours, "+apps.size()+" apps.")).addOnFailureListener(e->status.setText("Usage report upload failed: "+e.getMessage()));}catch(Exception e){status.setText("Usage report error: "+e.getMessage());}}
 void enableLocationStart(){if(startLocation!=null)startLocation.setEnabled(true);status.setText("Location permission granted. Tap Start visible location sharing when ready.");}
 void startLocationSharing(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED&&checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED){status.setText("Location permission is required first.");return;}Intent i=new Intent(this,LocationSessionService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);status.setText("Location sharing started. Android shows an ongoing location notification.");}
 @Override public void onRequestPermissionsResult(int c,String[] p,int[] r){super.onRequestPermissionsResult(c,p,r);boolean ok=r.length>0&&r[0]==android.content.pm.PackageManager.PERMISSION_GRANTED;if(c==103&&ok)enableLocationStart();else if(c==103)status.setText("Location permission denied. Sharing remains off.");else if(c==101||c==102)status.setText(ok?"Permission granted. No capture starts automatically.":"Permission denied. Capture remains off.");else if(c==107){if(ok)startAudioRecording();else status.setText("Microphone permission denied. Audio recording remains off.");}}
 @Override protected void onStop(){if(recordingAudio)cancelAudioRecording();super.onStop();}
 @Override protected void onDestroy(){if(listener!=null)listener.remove();if(screenRequestListener!=null)screenRequestListener.remove();cancelAudioRecording();super.onDestroy();}
}